<?php
declare(strict_types=1);
require_once __DIR__ . '/../../config/ui.php';
require_login('ADMIN');
$id = filter_input(INPUT_GET, 'id', FILTER_VALIDATE_INT);
if (!$id) { http_response_code(400); exit('Associado inválido.'); }
$stmt = $pdo->prepare("SELECT * FROM usuarios WHERE id = :id AND perfil = 'ASSOCIADO' LIMIT 1");
$stmt->execute([':id' => $id]);
$u = $stmt->fetch();
if (!$u) { http_response_code(404); exit('Associado não encontrado.'); }
$pay = $pdo->prepare('SELECT * FROM mensalidades WHERE associado_id = :id ORDER BY ano_referencia DESC, mes_referencia DESC LIMIT 12');
$pay->execute([':id' => $id]);
$payments = $pay->fetchAll();
$status = ['EM_DIA'=>['Em dia','bg-green-50 text-green-700'],'DEVEDOR'=>['Pendente','bg-amber-50 text-amber-700'],'DESFILIADO'=>['Desfiliado','bg-red-50 text-red-700']][$u['status_financeiro']] ?? ['Indefinido','bg-slate-100 text-slate-600'];
admin_start('Perfil do associado','associados.php');
?><div class="mb-8 flex flex-col justify-between gap-4 md:flex-row md:items-end"><div><a href="<?=e(app_url('admin/associados.php'))?>" class="text-sm font-semibold text-blue-600">← Voltar para associados</a><h2 class="mt-3 text-3xl font-extrabold">Perfil do associado</h2></div><a href="<?=e(app_url('admin/card.php?id='.(int)$u['id']))?>" class="rounded-lg bg-slate-900 px-5 py-3 text-sm font-bold text-white">Baixar card</a><a href="<?=e(app_url('admin/editar_associado.php?id='.(int)$u['id']))?>" class="rounded-lg border border-slate-200 bg-white px-5 py-3 text-sm font-semibold hover:border-blue-500 hover:text-blue-600">Editar cadastro</a></div><div class="grid gap-6 xl:grid-cols-3"><section class="shadow-soft rounded-xl border border-slate-100 bg-white p-7 xl:col-span-1"><div class="flex items-center gap-4"><div class="grid h-16 w-16 place-items-center rounded-2xl bg-blue-100 text-2xl font-bold text-blue-700"><?=e(strtoupper(substr($u['nome'],0,1)))?></div><div><h3 class="font-bold"><?=e($u['nome'])?></h3><p class="text-sm text-slate-400"><?=e($u['email'])?></p></div></div><div class="mt-7 space-y-4 border-t border-slate-100 pt-6 text-sm"><div><p class="text-xs text-slate-400">Matrícula</p><b><?=e($u['matricula'])?></b></div><div><p class="text-xs text-slate-400">CPF</p><b><?=e($u['cpf'])?></b></div><div><p class="text-xs text-slate-400">Data de filiação</p><b><?=e(date('d/m/Y',strtotime($u['data_filiacao'])))?></b></div><div><p class="text-xs text-slate-400">Status atual</p><span class="mt-1 inline-block rounded-full px-3 py-1 text-xs font-semibold <?=$status[1]?>"><?=e($status[0])?></span></div></div></section><section class="shadow-soft rounded-xl border border-slate-100 bg-white p-7 xl:col-span-2"><div class="mb-6"><h3 class="font-bold">Histórico financeiro</h3><p class="mt-1 text-xs text-slate-400">Últimas mensalidades registradas</p></div><div class="overflow-x-auto"><table class="w-full text-left text-sm"><thead class="border-b border-slate-100 text-xs uppercase tracking-wider text-slate-400"><tr><th class="pb-3">Referência</th><th class="pb-3">Vencimento</th><th class="pb-3">Valor</th><th class="pb-3">Status</th></tr></thead><tbody><?php foreach($payments as $p):$paid=$p['status_pagamento']==='PAGO';?><tr class="border-b border-slate-50"><td class="py-4 font-semibold"><?=e(sprintf('%02d/%04d',$p['mes_referencia'],$p['ano_referencia']))?></td><td class="py-4 text-slate-500"><?=e(date('d/m/Y',strtotime($p['data_vencimento'])))?></td><td class="py-4">R$ <?=e(number_format((float)$p['valor'],2,',','.'))?></td><td class="py-4"><span class="rounded-full px-3 py-1 text-xs font-semibold <?=$paid?'bg-green-50 text-green-700':'bg-amber-50 text-amber-700'?>"><?=e($paid?'Pago':'Pendente')?></span></td></tr><?php endforeach;?></tbody></table><?php if(!$payments):?><p class="py-10 text-center text-sm text-slate-400">Nenhuma mensalidade encontrada.</p><?php endif;?></div></section></div><?php admin_end();